INSERT INTO iam.role_capabilities(tenant_id,role_id,capability_id,effect,conditions,granted_by)
SELECT decision.tenant_id,decision.role_id,intent.id,decision.effect,decision.conditions,decision.granted_by
FROM iam.capabilities intent
JOIN iam.capabilities base ON base.code=intent.ui_metadata->>'base_capability'
JOIN iam.role_capabilities decision ON decision.capability_id=base.id
WHERE intent.ui_metadata ? 'base_capability'
ON CONFLICT(tenant_id,role_id,capability_id) DO NOTHING;

INSERT INTO iam.user_capabilities(tenant_id,user_id,capability_id,effect,conditions,valid_from,valid_until,granted_by)
SELECT decision.tenant_id,decision.user_id,intent.id,decision.effect,decision.conditions,decision.valid_from,decision.valid_until,decision.granted_by
FROM iam.capabilities intent
JOIN iam.capabilities base ON base.code=intent.ui_metadata->>'base_capability'
JOIN iam.user_capabilities decision ON decision.capability_id=base.id
WHERE intent.ui_metadata ? 'base_capability'
ON CONFLICT DO NOTHING;

UPDATE platform.commercial_plans plan
SET limits=jsonb_set(plan.limits,'{permissions,permissoes}',
  COALESCE((SELECT jsonb_agg(DISTINCT code) FROM (
     SELECT jsonb_array_elements_text(plan.limits->'permissions'->'permissoes') AS code
     UNION ALL
     SELECT intent.code FROM iam.capabilities intent
     WHERE intent.ui_metadata ? 'base_capability'
       AND (plan.limits->'permissions'->'permissoes') ? (intent.ui_metadata->>'base_capability')
   ) retained), '[]'::jsonb))
WHERE jsonb_typeof(plan.limits->'permissions'->'permissoes')='array';

-- A rota agregada utiliza as permissões das operações reais de criar/editar checklist.
UPDATE iam.capabilities SET status='INACTIVE' WHERE code='access.post.maintenance.checklists.save';
COMMIT;
